// ABOUTME: Writes a checked rule list as Seatbelt text plus a sorted -D parameter list.
// ABOUTME: The only code that writes SBPL; config-derived values appear only as (param "...") references.
//! Emission.
//!
//! Parameters are numbered per kind in order of first use (`R0`, `R1`, `W0`, ...), and equal
//! values share one name, so the same rule list always produces the same text and parameters.
//! Static text comes from `&'static str` values written in this crate; the only dynamic text is
//! the [`LogTag`], which is hexadecimal and generated by `hb`.

use std::collections::HashMap;
use std::fmt::Write as _;

use snafu::{Snafu, ensure};

use super::rule::{Action, Filter, ParamKind, ParamValue, Rule, Section};

/// A per-session token that tags denials so `--log-denials` can pick them out of the system log.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LogTag(String);

/// Why a [`LogTag`] was refused.
#[derive(Debug, Snafu, PartialEq, Eq)]
#[snafu(display("a log tag is 8 to 32 lowercase hexadecimal digits"))]
pub struct LogTagError;

impl LogTag {
    /// A tag from `hex`.
    ///
    /// # Errors
    /// [`LogTagError`] unless `hex` is 8 to 32 lowercase hexadecimal digits.
    pub fn new(hex: &str) -> Result<Self, LogTagError> {
        ensure!(
            (8..=32).contains(&hex.len())
                && hex
                    .bytes()
                    .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)),
            LogTagSnafu
        );
        Ok(Self(hex.to_owned()))
    }

    /// A tag made of `bits` as 16 hexadecimal digits. It always satisfies [`LogTag::new`].
    #[must_use]
    pub fn from_bits(bits: u64) -> Self {
        Self(format!("{bits:016x}"))
    }

    /// The tag text.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// Something worth knowing about a profile that is not an error.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub enum RenderWarning {
    /// The profile is large enough that `sandbox-exec` takes noticeable time to compile it.
    LargeProfile {
        /// The number of filters.
        weight: usize,
        /// The count at which this warning starts.
        warn_at: usize,
    },
}

impl std::fmt::Display for RenderWarning {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::LargeProfile { weight, warn_at } => write!(
                f,
                "the profile has {weight} filters (warning from {warn_at}); sandbox-exec compile time grows roughly with the square"
            ),
        }
    }
}

/// A rendered profile: the text and the `-D name=value` parameters it refers to.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Profile {
    /// The Seatbelt profile.
    pub text: String,
    /// `(name, value)` pairs, in order of first use.
    pub params: Vec<(String, String)>,
    /// Things to report, in order.
    pub warnings: Vec<RenderWarning>,
}

impl Profile {
    /// The `-D name=value` arguments for `sandbox-exec`.
    #[must_use]
    pub fn define_args(&self) -> Vec<String> {
        self.params
            .iter()
            .flat_map(|(name, value)| ["-D".to_owned(), format!("{name}={value}")])
            .collect()
    }
}

/// Names parameters and remembers which values already have one.
#[derive(Default)]
struct Params {
    names: HashMap<ParamValue, String>,
    counters: HashMap<ParamKind, usize>,
    ordered: Vec<(String, String)>,
}

impl Params {
    fn name(&mut self, value: &ParamValue) -> String {
        if let Some(name) = self.names.get(value) {
            return name.clone();
        }
        let name = if value.kind == ParamKind::Proxy {
            value.kind.prefix().to_owned()
        } else {
            let counter = self.counters.entry(value.kind).or_insert(0);
            let name = format!("{}{counter}", value.kind.prefix());
            *counter += 1;
            name
        };
        self.names.insert(value.clone(), name.clone());
        self.ordered.push((name.clone(), value.text.clone()));
        name
    }
}

fn filter_text(filter: &Filter, params: &mut Params) -> String {
    let mut named =
        |kind: &str, value: &ParamValue| format!("({kind} (param \"{}\"))", params.name(value));
    match filter {
        Filter::Subpath(v) => named("subpath", v),
        Filter::Literal(v) => named("literal", v),
        Filter::Regex(v) => named("regex", v),
        Filter::PathAncestors(v) => named("path-ancestors", v),
        Filter::RemoteIp(v) => format!("(remote ip (param \"{}\"))", params.name(v)),
        Filter::LocalIp(v) => format!("(local ip (param \"{}\"))", params.name(v)),
        Filter::RemoteUnixSocket(v) => {
            format!(
                "(remote unix-socket (subpath (param \"{}\")))",
                params.name(v)
            )
        }
        Filter::RemoteUnixSocketLiteral(v) => {
            format!(
                "(remote unix-socket (path-literal (param \"{}\")))",
                params.name(v)
            )
        }
        Filter::GlobalName(t) => format!("(global-name \"{t}\")"),
        Filter::PreferenceDomain(t) => format!("(preference-domain \"{t}\")"),
        Filter::StaticSubpath(t) => format!("(subpath \"{t}\")"),
        Filter::StaticLiteral(t) => format!("(literal \"{t}\")"),
        Filter::StaticRegex(t) => format!("(regex #\"{t}\")"),
        Filter::TargetSameSandbox => "(target same-sandbox)".to_owned(),
    }
}

/// The message clause: `(with message "hb-<tag>[ <label>]")`, or nothing without a tag.
fn message(tag: Option<&LogTag>, label: Option<&str>) -> String {
    match (tag, label) {
        (None, _) => String::new(),
        (Some(tag), None) => format!(" (with message \"hb-{}\")", tag.as_str()),
        (Some(tag), Some(label)) => format!(" (with message \"hb-{} {label}\")", tag.as_str()),
    }
}

/// Writes `rules` (already checked, in section order) as a profile.
#[must_use]
pub(crate) fn emit(rules: &[Rule], tag: Option<&LogTag>) -> Profile {
    let mut params = Params::default();
    let mut text = String::new();
    // Writing to a `String` cannot fail.
    let _ = writeln!(text, "(version 1)");
    let _ = writeln!(text, "(deny default{})", message(tag, None));
    let _ = writeln!(text, "(import \"system.sb\")");
    let mut section: Option<Section> = None;
    for rule in rules {
        if section != Some(rule.section) {
            section = Some(rule.section);
            let _ = writeln!(text, "; {}", rule.section);
        }
        let action = rule.action.to_string();
        let ops: Vec<String> = rule.ops.iter().map(ToString::to_string).collect();
        let filters: Vec<String> = rule
            .filters
            .iter()
            .map(|f| filter_text(f, &mut params))
            .collect();
        let clause = if rule.action == Action::Deny {
            message(tag, rule.label)
        } else {
            String::new()
        };
        let mut line = format!("({action} {}{clause}", ops.join(" "));
        for filter in &filters {
            line.push(' ');
            line.push_str(filter);
        }
        line.push(')');
        let _ = writeln!(text, "{line}");
    }
    Profile {
        text,
        params: params.ordered,
        warnings: Vec::new(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::seatbelt::rule::Op;
    use claims::{assert_err, assert_ok};
    use pretty_assertions::assert_eq;

    fn pv(kind: ParamKind, text: &str) -> ParamValue {
        ParamValue::new(kind, text)
    }

    #[test]
    fn a_tag_from_bits_is_sixteen_hex_digits_and_passes_the_same_check_as_new() {
        for bits in [0, 1, 0xdead_beef, u64::MAX] {
            let tag = LogTag::from_bits(bits);
            assert_eq!(tag.as_str().len(), 16);
            assert_eq!(assert_ok!(LogTag::new(tag.as_str())), tag);
        }
        assert_eq!(LogTag::from_bits(255).as_str(), "00000000000000ff");
    }

    #[test]
    fn a_log_tag_is_short_lowercase_hex() {
        assert_ok!(LogTag::new("0123abcd"));
        assert_ok!(LogTag::new(&"f".repeat(32)));
        for bad in [
            "",
            "abc",
            "ABCDEF01",
            "0123abcg",
            &"a".repeat(33),
            "0123 abc",
        ] {
            assert_err!(LogTag::new(bad));
        }
    }

    #[test]
    fn the_header_is_version_deny_default_and_the_system_import() {
        let profile = emit(&[], None);
        assert_eq!(
            profile.text,
            "(version 1)\n(deny default)\n(import \"system.sb\")\n"
        );
        assert!(profile.params.is_empty());
    }

    #[test]
    fn a_tag_goes_into_the_default_deny_and_every_deny_but_not_allows() {
        let tag = assert_ok!(LogTag::new("deadbeef"));
        let rules = [
            Rule::allow(Section::Process, &[Op::ProcessExec], vec![]),
            Rule::deny(
                Section::Floor,
                &[Op::FileWriteAll],
                vec![Filter::Subpath(pv(ParamKind::Deny, "/x"))],
            )
            .labelled("floor"),
        ];
        let text = emit(&rules, Some(&tag)).text;
        assert!(
            text.contains("(deny default (with message \"hb-deadbeef\"))"),
            "{text}"
        );
        assert!(text.contains("(allow process-exec)\n"), "{text}");
        assert!(
            text.contains(
                "(deny file-write* (with message \"hb-deadbeef floor\") (subpath (param \"F0\")))"
            ),
            "{text}"
        );
    }

    #[test]
    fn parameters_are_named_per_kind_in_order_of_first_use_and_shared_by_value() {
        let rules = [
            Rule::allow(
                Section::Grants,
                &[Op::FileReadAll],
                vec![
                    Filter::Subpath(pv(ParamKind::Read, "/a")),
                    Filter::Subpath(pv(ParamKind::Read, "/b")),
                ],
            ),
            Rule::allow(
                Section::Grants,
                &[Op::FileReadAll, Op::FileWriteAll],
                vec![Filter::Subpath(pv(ParamKind::Write, "/a"))],
            ),
            Rule::allow(
                Section::Metadata,
                &[Op::FileReadData],
                vec![Filter::PathAncestors(pv(ParamKind::Ancestor, "/a"))],
            ),
            Rule::allow(
                Section::Grants,
                &[Op::FileReadAll],
                vec![Filter::Subpath(pv(ParamKind::Read, "/a"))],
            ),
        ];
        let profile = emit(&rules, None);
        assert_eq!(
            profile.params,
            [
                ("R0".to_owned(), "/a".to_owned()),
                ("R1".to_owned(), "/b".to_owned()),
                ("W0".to_owned(), "/a".to_owned()),
                ("A0".to_owned(), "/a".to_owned()),
            ]
        );
        assert!(
            profile
                .text
                .contains("(subpath (param \"R0\")) (subpath (param \"R1\"))")
        );
        assert_eq!(profile.text.matches("(param \"R0\")").count(), 2);
    }

    #[test]
    fn the_proxy_has_a_fixed_name() {
        let rules = [Rule::allow(
            Section::Network,
            &[Op::NetworkOutbound],
            vec![Filter::RemoteIp(pv(ParamKind::Proxy, "localhost:1"))],
        )];
        let profile = emit(&rules, None);
        assert_eq!(
            profile.params,
            [("PROXY".to_owned(), "localhost:1".to_owned())]
        );
        assert!(
            profile
                .text
                .contains("(allow network-outbound (remote ip (param \"PROXY\")))")
        );
    }

    #[test]
    fn every_filter_form_has_its_seatbelt_spelling() {
        let rules = [Rule::allow(
            Section::Grants,
            &[Op::FileReadAll],
            vec![
                Filter::Literal(pv(ParamKind::Read, "/l")),
                Filter::Regex(pv(ParamKind::Regex, "^/r/[^/]+$")),
                Filter::StaticSubpath("/usr"),
                Filter::StaticLiteral("/dev/stdout"),
                Filter::StaticRegex("^/dev/fd/[0-9]+$"),
            ],
        )];
        let text = emit(&rules, None).text;
        assert!(
            text.contains(
                "(allow file-read* (literal (param \"R0\")) (regex (param \"G0\")) (subpath \"/usr\") (literal \"/dev/stdout\") (regex #\"^/dev/fd/[0-9]+$\"))"
            ),
            "{text}"
        );
        let more = [
            Rule::allow(
                Section::Tls,
                &[Op::MachLookup],
                vec![Filter::GlobalName("com.apple.trustd")],
            ),
            Rule::allow(
                Section::Tls,
                &[Op::UserPreferenceRead],
                vec![Filter::PreferenceDomain("kCFPreferencesAnyApplication")],
            ),
            Rule::allow(
                Section::Process,
                &[Op::Signal],
                vec![Filter::TargetSameSandbox],
            ),
            Rule::allow(
                Section::Network,
                &[Op::NetworkBind],
                vec![Filter::LocalIp(pv(ParamKind::Bind, "localhost:24282"))],
            ),
            Rule::deny(
                Section::Floor,
                &[Op::NetworkOutbound],
                vec![Filter::RemoteUnixSocket(pv(
                    ParamKind::Socket,
                    "/var/run/docker.sock",
                ))],
            ),
            Rule::allow(
                Section::Network,
                &[Op::NetworkOutbound],
                vec![Filter::RemoteUnixSocketLiteral(pv(
                    ParamKind::Socket,
                    "/private/tmp/hb/ctl.sock",
                ))],
            ),
        ];
        let text = emit(&more, None).text;
        for expected in [
            "(allow mach-lookup (global-name \"com.apple.trustd\"))",
            "(allow user-preference-read (preference-domain \"kCFPreferencesAnyApplication\"))",
            "(allow signal (target same-sandbox))",
            "(allow network-bind (local ip (param \"B0\")))",
            "(deny network-outbound (remote unix-socket (subpath (param \"K0\"))))",
            "(allow network-outbound (remote unix-socket (path-literal (param \"K1\"))))",
        ] {
            assert!(text.contains(expected), "{expected} missing from {text}");
        }
    }

    #[test]
    fn a_section_comment_precedes_each_run_of_one_section() {
        let rules = [
            Rule::allow(Section::Process, &[Op::ProcessExec], vec![]),
            Rule::allow(Section::Process, &[Op::ProcessFork], vec![]),
            Rule::allow(Section::Metadata, &[Op::FileReadMetadata], vec![]),
        ];
        let text = emit(&rules, None).text;
        assert_eq!(text.matches("; process\n").count(), 1);
        assert_eq!(text.matches("; metadata\n").count(), 1);
    }

    #[test]
    fn a_hostile_param_value_never_reaches_the_text() {
        let hostile = "/x\") (allow file-read* (subpath \"/\"))(\"";
        let rules = [Rule::allow(
            Section::Grants,
            &[Op::FileReadAll],
            vec![Filter::Subpath(pv(ParamKind::Read, hostile))],
        )];
        let profile = emit(&rules, None);
        assert!(!profile.text.contains("allow file-read* (subpath \"/\")"));
        assert!(!profile.text.contains(hostile));
        assert_eq!(profile.params[0].1, hostile);
    }

    #[test]
    fn define_args_are_dash_d_pairs_in_order() {
        let profile = Profile {
            text: String::new(),
            params: vec![("R0".into(), "/a b".into()), ("W0".into(), "/c".into())],
            warnings: Vec::new(),
        };
        assert_eq!(profile.define_args(), ["-D", "R0=/a b", "-D", "W0=/c"]);
    }
}
